private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.next = null;
    node.prev = null;
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // get the previous and next elements in the list
    ListNodeImpl<E> previous = node.getPrevious();
    ListNodeImpl<E> next = node.getNext();

    // if the previous element is null, then the node is the head of the list
    if (previous == null) {
        // update the head of the list
        head = next;
    } else {
        // update the next element of the previous element
        previous.setNext(next);
    }

    // if the next element is null, then the node is the tail of the list
    if (next == null) {
        // update the tail of the list
        tail = previous;
    } else {
        // update the previous element of the next element
        next.setPrevious(previous);
    }

    // update the list size
    size--;

    return true;
}

void unlink(ListNodeImpl<?> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<?> prevNode = node.getPrev();
    ListNodeImpl<?> nextNode = node.getNext();

    // Handle the case where node is not in the list (unlinked)
    if (prevNode == null || nextNode == null) {
        return false;
    }

    // Update the previous and next nodes to point to each other
    prevNode.setNext(nextNode);
    nextNode.setPrev(prevNode);

    // Update the size of the list
    size--;

    return true;
}

