private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize variables for traversing the graph
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    boolean satisfied = false;

    // Traverse the graph until the desired node is found or the stop node is reached
    while (!satisfied) {
        // Check if the current node satisfies the predicate
        if (predicate.test(circulator.current())) {
            // If so, return the circulator to the current node
            return circulator;
        }

        // Move to the next node in the traversal direction
        circulator.incr();

        // Check if the stop node has been reached
        if (circulator.current() == stop) {
            // If so, return the circulator to the stop node
            return circulator;
        }
    }

    // If the desired node was not found, return a circulator to the stop node
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    while (!circulator.isDone() && !predicate.test(circulator.getNode())) {
        circulator.next();
    }
    if (circulator.isDone()) return new OuterFaceCirculator(stop);
    return circulator;
}

