    // Find the first node in the component satisfying the predicate
    OuterFaceCirculator curr = start.getOuterFaceCirculator(dir);
    while (curr != null && !predicate.test(curr.getNode())) {
        curr = curr.getNext(dir);
    }

    // If we reached the stop node before finding a match, return a circulator to stop
    if (curr == stop) {
        return stop.getOuterFaceCirculator(dir);
    }

    // Otherwise, return a circulator to the matching node
    return curr;
}

