    Set<Integer> vertexIndices = new HashSet<>();

    // Iterate over the vertices and add their indices to the set
    for (V vertex : vertices) {
        int index = graph.getVertexIndex(vertex);
        vertexIndices.add(index);
    }

    // Check if all pairs of vertices in the induced subgraph are adjacent
    for (int i = 0; i < vertexIndices.size(); i++) {
        for (int j = i + 1; j < vertexIndices.size(); j++) {
            if (!graph.hasEdge(index1, index2)) {
                return false;
            }
        }
    }

