    // Iterate over the vertices of the subgraph
    for (V vertex : subgraphVertices) {
        // Iterate over the neighbors of the current vertex in the subgraph
        for (V neighbor : graph.neighborsOf(vertex)) {
            // If the neighbor is not in the subgraph, return false
            if (!vertices.contains(neighbor)) {
