public LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    Preconditions.checkNotNull(str, "String parameter cannot be null");
    Preconditions.checkNotNull(session, "WriteSession parameter cannot be null");
    Preconditions.checkNotNull(lb, "LinkedBuffer parameter cannot be null");
    // negotiate constant size
    try {
        final int utflen = str.length();
    } catch (NullPointerException e) {
        throw new NullPointerException("String parameter cannot be null");
    }
    final int count = utflen * 3;
    if (lb.buffer().capacity() < count) {
        final LinkedBuffer lb2 = lb.buffer().slice(0, count);
